 static int Main(){string nonce=new string('a',32),digest=new string('b',64);Check(Reject(()=>new UsbExactBlockGpo(@"SOFTWARE\Policies\Microsoft\Windows\DeviceInstall\Restrictions",nonce,()=>{})));string first=@"USB\VID_0001&PID_0001&MI_00\SYNTHETIC_A",second=@"USB\VID_0001&PID_0002\SYNTHETIC_B";var image=UsbExactBlockGpo.Desired(1,digest,new[]{first,second});Check(image.Values.Count==5);Check(image.Values["DenyInstanceIDs\\1"].Equals(first));Check(!image.Values.ContainsKey("AllowInstanceIDs"));Check(!image.Values.ContainsKey("DenyDeviceIDs"));Check(UsbExactBlockGpo.Same(UsbExactBlockGpo.Empty(),UsbExactBlockGpo.Desired(2,digest,new string[0])));Check(Reject(()=>UsbExactBlockGpo.Desired(1,digest,new[]{@"USB\ROOT_HUB30\X"})));Check(Reject(()=>UsbExactBlockGpo.Desired(1,digest,new[]{first,first})));Check(Reject(()=>UsbExactBlockGpo.ValidateTombstones(new UsbExactBlockGpo.Image(new Dictionary<string,object>(),new[]{"DenyInstanceIDs\\32"}),UsbExactBlockGpo.Empty(),image)));UsbExactBlockGpo.ValidateTombstones(new UsbExactBlockGpo.Image(new Dictionary<string,object>(),new[]{"DenyInstanceIDs\\1"}),UsbExactBlockGpo.Empty(),image);var overlay=new UsbExactBlockGpo(@"SOFTWARE\Sentinel\ExactBlockQualification\"+nonce,nonce,()=>{},nonce);var managed=overlay.Managed(image);Check(managed.Values.Count==3);Check(!managed.Values.ContainsKey("DenyInstanceIDs"));Check(!managed.Values.ContainsKey("DenyInstanceIDsRetroactive"));Check(UsbExactBlockGpo.Same(overlay.Managed(UsbExactBlockGpo.Empty()),UsbExactBlockGpo.Empty()));var leaked=image.Values;leaked.Clear();Check(image.Values.Count==5);Console.WriteLine("PASS exact policy image, empty-last-block baseline, immutable entries and live-path refusal; no registry action");return 0;}
